 void RefreshMapEntityStates(bool restoring=false){if(ActiveMap==null||ActiveMap.entities==null)return;foreach(var e in ActiveMap.entities.objects){GameObject root;if(!mapEntityObjects.TryGetValue(e.id,out root))continue;var visual=root.GetComponent<RefugeDeviceVisual>();if(visual!=null&&visual.portal)visual.transferActive=refuge.unlockedNodes.Contains(e.id);if(e.kind==DungeonEntityKind.Chest){root.SetActive(!(e.chestKind==DungeonChestKind.Mimic&&EntityState(e.id).opened));var chest=root.GetComponent<DungeonChestVisual>();if(chest!=null)chest.SetOpened(EntityState(e.id).opened);}DungeonDoor door;if(e.kind==DungeonEntityKind.Door&&mapDoors.TryGetValue(e.id,out door)){if(e.cityEntrance||e.returnToDigitalKingdom){door.KeepOpenPermanently();EntityState(e.id).opened=true;continue;}if(restoring)door.ResetPermanentOpen();if(RestorePermanentKeyDoor(e,door)){}else if(e.doorKind==DungeonDoorKind.Locked&&!HasMapKey(e.requiredKeyId)&&!ConnectionUnlocked(e.id)){EntityState(e.id).opened=false;door.SetClosedImmediately();}else if(EntityState(e.id).opened)door.SetOpenImmediately();else if(restoring)door.SetClosedImmediately();}}}
 bool MapNpcBlocks(Vector2Int cell){if(ActiveMap==null||ActiveMap.entities==null)return false;return ActiveMap.entities.objects.Exists(e=>(e.kind==DungeonEntityKind.NPC||e.kind==DungeonEntityKind.Chest||e.kind==DungeonEntityKind.Savepoint||e.kind==DungeonEntityKind.Switch)&&e.cell==cell&&!(e.kind==DungeonEntityKind.Chest&&e.chestKind==DungeonChestKind.Mimic&&EntityState(e.id).opened));}
 bool MapDoorsBlock(Vector3 from,Vector3 to){foreach(var door in mapDoors.Values)if(door!=null&&door.Blocks(from,to))return true;return false;}
 bool HasMapKey(string id){if(ownedEquipment.Contains(id))return true;int i=Array.FindIndex(inventorySettings.items,item=>item!=null&&item.id==id);return i>=0&&itemCounts[i]>0;}
 bool FacingMapTeleport(DungeonMapEntity e){GameObject root;return mapEntityObjects.TryGetValue(e.id,out root)&&LookingToward(root.transform.TransformPoint(new Vector3(1.65f,.57f,.4f)));}
 DungeonMapEntity NearbyMapEntity(){if(ActiveMap==null||ActiveMap.entities==null)return null;foreach(var e in ActiveMap.entities.objects){if(e.kind==DungeonEntityKind.Chest&&e.chestKind==DungeonChestKind.Mimic&&EntityState(e.id).opened)continue;if(e.kind==DungeonEntityKind.Teleport){if(e.cell==position&&FacingMapTeleport(e))return e;}else if(e.kind==DungeonEntityKind.Door){if(e.cityEntrance||e.returnToDigitalKingdom)continue;DungeonDoor door;if(mapDoors.TryGetValue(e.id,out door)&&DoorInteractionAvailable(door))return e;}else if(FacingRefugeNpc(e.cell)&&FacingMapEntity(e))return e;}return null;}
 bool UpdateMapEntityInput(){if(worldDialogue.Active||IntroductionActive||battle||moving||lost||pauseOpen)return false;var k=Keyboard.current;if(k==null||!k.eKey.wasPressedThisFrame)return false;var e=NearbyMapEntity();if(e==null)return false;InteractMapEntity(e);return true;}
 void InteractMapEntity(DungeonMapEntity e){
  if(e.kind==DungeonEntityKind.Switch){GameObject root;if(mapEntityObjects.TryGetValue(e.id,out root))root.GetComponent<DungeonSwitch>().Trigger();return;}
  if(e.interaction!=null){if(!DungeonConditionsMet(e.interaction)){message=e.interaction.deniedMessage;return;}if((!e.interaction.continueLegacy||LegacyEntityReady(e))&&!ProfileAdapter(e.id,e.interaction,()=>InteractMapEntity(e)))return;}

  if(e.kind==DungeonEntityKind.NPC){GameObject focusActor;if(mapEntityObjects.TryGetValue(e.id,out focusActor))FocusConversationOn(focusActor.transform);var npc=e.npcCatalog!=null?Array.Find(e.npcCatalog.npcs,n=>n.id==e.npcId):null;if(e.dialogue.Length>0)worldDialogue.Begin(e.dialogue);else if(npc!=null&&npc.conversations!=null&&npc.conversations.Length>0){var state=NpcState(e.id);var text=npc.conversations[Mathf.Min(state.talks,npc.conversations.Length-1)];worldDialogue.Begin(new[]{new WorldDialogueLine(npc.displayName,text)},()=>state.talks++);}}
