  else if(e.kind==DungeonEntityKind.Door){if(e.returnToDigitalKingdom){ReturnFromKingdomDoor();return;}if(e.cityEntrance&&!CityBossDefeated()){worldDialogue.Begin(new[]{new WorldDialogueLine("SISTEMA","La puerta espera la derrota de Makong.")});return;}if(e.doorKind==DungeonDoorKind.Locked&&!EntityState(e.id).keyConsumed&&!HasMapKey(e.requiredKeyId)&&!ConnectionUnlocked(e.id)){var access=e.doorAccess==DigitalDoorAccess.Automatic?DigitalDoorVisual.AccessFor(e.requiredKeyId):e.doorAccess;var code=access==DigitalDoorAccess.Root?SystemMessageCode.DeniedRoot:access==DigitalDoorAccess.Red?SystemMessageCode.DeniedRed:access==DigitalDoorAccess.Green?SystemMessageCode.DeniedGreen:SystemMessageCode.Denied;SystemMessages.Show(code,"",0,DigitalIcon.Denied,e.accessDeniedMessage);return;}if(e.doorKind==DungeonDoorKind.Locked&&!EntityState(e.id).keyConsumed&&!ConnectionUnlocked(e.id)&&!mapDoors[e.id].IsOpening)pendingDoorKeys.Add(e.id);mapDoors[e.id].OpenDoor();}
