  if(received){EntityState(e.id).opened=true;if(e.chestKind==DungeonChestKind.Mimic)mapEntityObjects[e.id].SetActive(false);if(string.IsNullOrEmpty(e.contentId)&&e.chestRewards==null&&e.chestKind!=DungeonChestKind.Mimic)message="El cofre está vacío.";}
