 void ExamineMapNode(DungeonMapEntity e){bool first=!refuge.unlockedNodes.Contains(e.id);if(first)refuge.unlockedNodes.Add(e.id);RefreshMapEntityStates();transferChoices=AvailableTransferNodes(e.id);Action show=()=>{transferSelection=0;transferMenu=transferChoices.Count>0;};Action ready=()=>{if(!TryRevealNodeMap(e.id,show))show();};if(first||transferChoices.Count==0)worldDialogue.Begin(new[]{new WorldDialogueLine("SISTEMA",transferChoices.Count==0?"Ningún otro nodo disponible.":"Nodo registrado: "+e.displayName+".")},ready);else ready();}
 List<TransferNodeDefinition> AvailableTransferNodes(string origin){
