 void TravelMapDoor(DungeonMapEntity e){if(e.returnToDigitalKingdom){ReturnFromKingdomDoor();return;}if(e.cityEntrance){EnterDigitalKingdomAt(e.cell,(e.heading+2)%4);return;}if(e.destinationMap==null||e.destinationMap==ActiveMap){WarpPlayer(e.destinationCell,e.heading);message=e.destinationRegionId;return;}bool first;var data=DungeonMapPersistence.ForTravel(CaptureDungeonSave(),e.destinationMap,e.destinationCell,e.heading,out first);ReplaceFloor(e.destinationMap,data,first);}
